args.spec_json:
{
  "name": "ht_ates_screening",
  "description": "HT-ATES seasonal storage screening",
  "reference": "HEATSTORE: recovery efficiency 0.6-0.8",
  "inputs": {
    "summer_surplus_gwh": {
      "unit": "GWh"
    },
    "winter_boiler_gwh": {
      "unit": "GWh"
    },
    "annual_heat_gwh": {
      "unit": "GWh"
    }
  },
  "parameters": {
    "recovery_efficiency": {
      "value": 0.7
    },
    "storage_capacity_gwh": {
      "value": 25.0
    }
  },
  "outputs": {
    "stored_gwh": {
      "expr": "min(summer_surplus_gwh, storage_capacity_gwh)"
    },
    "recovered_gwh": {
      "expr": "stored_gwh * recovery_efficiency"
    },
    "boiler_after_gwh": {
      "expr": "max(0, winter_boiler_gwh - recovered_gwh)"
    }
  },
  "invariants": [
    "recovered_gwh <= stored_gwh",
    "boiler_after_gwh >= 0"
  ],
  "tests": [
    {
      "inputs": {
        "summer_surplus_gwh": 28.5,
        "winter_boiler_gwh": 31.5,
        "annual_heat_gwh": 111.67
      },
      "expect": {
        "recovered_gwh": 17.5,
        "boiler_after_gwh": 14.0
      }
    }
  ]
}
